 s=(out/'index.html').read_text(encoding='utf-8');s=re.sub(r'(?<=\?v=)[\w.-]+',STAMP,s);s=re.sub(r"window.MC_BUILD='[^']+'",f"window.MC_BUILD='{STAMP}'",s);s=s.replace('Modded Cycles — web flasher','Modded Cycles — MIDI page LED test').replace('../assets/release.js?','test-release.js?')
 intro='<p><strong data-l="en">MIDI B-side page LED test.</strong><strong data-l="fr">Test LEDs de pages MIDI B.</strong> <span data-l="en">The selected edit page is solid; the playing page blinks with stock timing. If both are the same page, that page blinks. Stopped playback shows only the selected page solid. Normal length mode follows A-side’s pattern length; per-track mode keeps independent MIDI lane lengths. Includes main 1.86 and optional CPU/CUT diagnostics. Main flasher unchanged.</span><span data-l="fr">Page editee fixe ; page jouee clignotante au rythme natif. Si elles coincident, cette page clignote. A l arret, seule la page editee reste fixe. Mode normal : longueur du pattern A ; mode par piste : longueurs MIDI independantes. Inclut le principal1.86 et les diagnostics CPU/CUT facultatifs. Principal inchange.</span></p>'
 s=s.replace('<main class="wrap fl">','<main class="wrap fl">'+intro).replace('</body>',f'<script src="beat-diagnostic-data.js?v={STAMP}"></script><script src="beat-diagnostic.js?v={STAMP}"></script><script src="midi-page-leds-data.js?v={STAMP}"></script><script src="midi-page-leds.js?v={STAMP}"></script></body>');(out/'index.html').write_text(s,encoding='utf-8');(out/'midi-page-leds-data.js').write_text('window.MCMidiPageLeds='+json.dumps(data,separators=(',',':'))+';\n',encoding='utf-8');shutil.copyfile(ROOT/'tools/web/midi-page-leds.js',out/'midi-page-leds.js')
 (out/'test-release.js').write_text('window.MC_RELEASES='+json.dumps([dict(version='MIDI-page-LED-test.1',date='2026-10-17',changes=[dict(en='B-side selected page solid, playing page blinking with stock timing. Normal length follows A-side; per-track mode keeps independent MIDI lengths. Optional diagnostics retained; main unchanged.',fr='B : page editee fixe, page jouee clignotante au rythme natif. Longueur normale liee a A ; longueurs MIDI independantes en mode par piste. Diagnostics facultatifs conserves ; principal inchange.')])])+';\n',encoding='utf-8');(out/'BUILD.json').write_text(json.dumps(dict(stamp=STAMP,scope='test-only',base='main1.86',main_unchanged=True),indent=2)+'\n',encoding='utf-8')
 (out/'TEST-NOTES.md').write_text('Test only: B-side selected page solid, playing page blinking with the native stock phase; when the same, blink takes priority. Stopped and paused: selected page solid. In normal scale mode all MIDI lane lengths follow the A-side common pattern length; choose per-track scale mode for independent MIDI lane length edits. A-side pattern data and MIDI speeds are unchanged. Test switching selected pages while another page plays, short and partial pages, six unequal lengths in per-track mode, exit/re-enter B, and REC. CPU/CUT diagnostic remains optional with repeat + SY. Main 1.86 unchanged.\n',encoding='utf-8')
 if a.check:
  for f in out.iterdir():assert f.read_bytes().replace(b'\r\n',b'\n')==(target/f.name).read_bytes().replace(b'\r\n',b'\n'),f.name
 print('PASS MIDI page LED test generator',len(raw),'bytes')
